/** Return the SVG string for `name`, optionally with a class on the root svg. */
export function icon(name: keyof typeof ICONS | string, cls?: string): string {
  const s = ICONS[name as string];
  if (!s) return '';
  return cls ? s.replace('<svg ', `<svg class="${cls}" `) : s;
}
